methods:
protected void lookAhead(@NotNull ATNState state,
                         @Nullable ATNState stopState,
                         @Nullable PredictionContext context,
                         @NotNull IntervalSet lookaheadSet,
                         @NotNull Set<ATNConfig> lookBusySet,
                         @NotNull BitSet ruleStack,
                         boolean seeThroughPredicates, boolean addEOF) {

    ATNConfig config = new ATNConfig(state, 0, context);
    if (!lookBusySet.add(config)) return;

    if (state == stopState) {
        handleStopState(context, lookaheadSet, addEOF);
        return;
    }

    if (state instanceof RuleStopState) {
        handleRuleStopState(context, lookaheadSet, stopState, ruleStack, seeThroughPredicates, addEOF);
        return;
    }

    processStateTransitions(state, stopState, context, lookaheadSet, lookBusySet, ruleStack, seeThroughPredicates, addEOF);
}

private void handleStopState(@Nullable PredictionContext context, @NotNull IntervalSet lookaheadSet, boolean addEOF) {
    if (context == null) {
        lookaheadSet.add(Token.EPSILON);
    } else if (context.isEmpty() && addEOF) {
        lookaheadSet.add(Token.EOF);
    }
}

private void handleRuleStopState(@Nullable PredictionContext context,
                                  @NotNull IntervalSet lookaheadSet,
                                  @Nullable ATNState stopState,
                                  @NotNull BitSet ruleStack,
                                  boolean seeThroughPredicates, boolean addEOF) {
    if (context == null) {
        lookaheadSet.add(Token.EPSILON);
    } else if (context.isEmpty() && addEOF) {
        lookaheadSet.add(Token.EOF);
    }

    if (context != PredictionContext.EMPTY) {
        for (int i = 0; i < context.size(); i++) {
            ATNState returnState = atn.states.get(context.getReturnState(i));
            boolean wasRemoved = ruleStack.get(returnState.ruleIndex);
            try {
                ruleStack.clear(returnState.ruleIndex);
                lookAhead(returnState, stopState, context.getParent(i), lookaheadSet, ruleStack, ruleStack, seeThroughPredicates, addEOF);
            } finally {
                if (wasRemoved) {
                    ruleStack.set(returnState.ruleIndex);
                }
            }
        }
    }
}

private void processStateTransitions(@NotNull ATNState state,
                                     @Nullable ATNState stopState,
                                     @Nullable PredictionContext context,
                                     @NotNull IntervalSet lookaheadSet,
                                     @NotNull Set<ATNConfig> lookBusySet,
                                     @NotNull BitSet ruleStack,
                                     boolean seeThroughPredicates, boolean addEOF) {
    int numTransitions = state.getNumberOfTransitions();
    for (int i = 0; i < numTransitions; i++) {
        Transition transition = state.transition(i);
        if (transition instanceof RuleTransition) {
            handleRuleTransition((RuleTransition) transition, stopState, context, lookaheadSet, lookBusySet, ruleStack, seeThroughPredicates, addEOF);
        } else if (transition instanceof PredicateTransition) {
            handlePredicateTransition((PredicateTransition) transition, lookaheadSet, context, seeThroughPredicates, stopState);
        } else if (transition.isEpsilon()) {
            lookAhead(transition.target, stopState, context, lookaheadSet, lookBusySet, ruleStack, seeThroughPredicates, addEOF);
        } else if (transition instanceof WildcardTransition) {
            lookaheadSet.addAll(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        } else {
            handleOtherTransitions(transition, lookaheadSet);
        }
    }
}

private void handleRuleTransition(RuleTransition transition,
                                   @Nullable ATNState stopState,
                                   @Nullable PredictionContext context,
                                   @NotNull IntervalSet lookaheadSet,
                                   @NotNull Set<ATNConfig> lookBusySet,
                                   @NotNull BitSet ruleStack,
                                   boolean seeThroughPredicates, boolean addEOF) {
    if (ruleStack.get(transition.target.ruleIndex)) {
        return;
    }

    PredictionContext newContext = SingletonPredictionContext.create(context, transition.followState.stateNumber);
    try {
        ruleStack.set(transition.target.ruleIndex);
        lookAhead(transition.target, stopState, newContext, lookaheadSet, lookBusySet, ruleStack, seeThroughPredicates, addEOF);
    } finally {
        ruleStack.clear(transition.target.ruleIndex);
    }
}

private void handlePredicateTransition(PredicateTransition transition,
                                       @NotNull IntervalSet lookaheadSet,
                                       @Nullable PredictionContext context,
                                       boolean seeThroughPredicates, @Nullable ATNState stopState) {
    if (seeThroughPredicates) {
        lookAhead(transition.target, stopState, context, lookaheadSet, lookBusySet, ruleStack, seeThroughPredicates, addEOF);
    } else {
        lookaheadSet.add(HIT_PRED);
    }
}

private void handleOtherTransitions(Transition transition, @NotNull IntervalSet lookaheadSet) {
    IntervalSet labels = transition.label();
    if (labels != null) {
        if (transition instanceof NotSetTransition) {
            labels = labels.complement(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        }
        lookaheadSet.addAll(labels);
    }
}

protected void _LOOK(@NotNull ATNState s,
                     @Nullable ATNState stopState,
                     @Nullable PredictionContext ctx,
                     @NotNull IntervalSet look,
                     @NotNull Set<ATNConfig> lookBusy,
                     @NotNull BitSet calledRuleStack,
                     boolean seeThruPreds, boolean addEOF) {
    ATNConfig c = new ATNConfig(s, 0, ctx);
    if (!lookBusy.add(c)) return;

    handleStopState(s, stopState, ctx, look, addEOF);

    if (s instanceof RuleStopState) {
        handleRuleStopState(ctx, stopState, look, calledRuleStack, seeThruPreds, addEOF);
        return;
    }

    processTransitions(s, stopState, ctx, look, lookBusy, calledRuleStack, seeThruPreds, addEOF);
}

private void handleStopState(ATNState s, ATNState stopState, PredictionContext ctx, IntervalSet look, boolean addEOF) {
    if (s == stopState) {
        if (ctx == null) {
            look.add(Token.EPSILON);
        } else if (ctx.isEmpty() && addEOF) {
            look.add(Token.EOF);
        }
    }
}

private void handleRuleStopState(PredictionContext ctx, ATNState stopState, IntervalSet look, BitSet calledRuleStack, boolean seeThruPreds, boolean addEOF) {
    if (ctx == null) {
        look.add(Token.EPSILON);
    } else if (ctx.isEmpty() && addEOF) {
        look.add(Token.EOF);
    }

    if (ctx != PredictionContext.EMPTY) {
        for (int i = 0; i < ctx.size(); i++) {
            ATNState returnState = atn.states.get(ctx.getReturnState(i));
            boolean removed = calledRuleStack.get(returnState.ruleIndex);
            try {
                calledRuleStack.clear(returnState.ruleIndex);
                _LOOK(returnState, stopState, ctx.getParent(i), look, lookBusy, calledRuleStack, seeThruPreds, addEOF);
            } finally {
                if (removed) {
                    calledRuleStack.set(returnState.ruleIndex);
                }
            }
        }
    }
}

private void processTransitions(ATNState s, ATNState stopState, PredictionContext ctx, IntervalSet look, Set<ATNConfig> lookBusy, BitSet calledRuleStack, boolean seeThruPreds, boolean addEOF) {
    int n = s.getNumberOfTransitions();
    for (int i = 0; i < n; i++) {
        Transition t = s.transition(i);
        if (t instanceof RuleTransition) {
            processRuleTransition((RuleTransition) t, stopState, ctx, look, lookBusy, calledRuleStack, seeThruPreds, addEOF);
        } else if (t instanceof PredicateTransition && seeThruPreds) {
            _LOOK(t.target, stopState, ctx, look, lookBusy, calledRuleStack, seeThruPreds, addEOF);
        } else if (t.isEpsilon()) {
            _LOOK(t.target, stopState, ctx, look, lookBusy, calledRuleStack, seeThruPreds, addEOF);
        } else if (t instanceof WildcardTransition) {
            look.addAll(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        } else {
            IntervalSet set = t.label();
            if (set != null) {
                if (t instanceof NotSetTransition) {
                    set = set.complement(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
                }
                look.addAll(set);
            }
        }
    }
}

private void processRuleTransition(RuleTransition t, ATNState stopState, PredictionContext ctx, IntervalSet look, Set<ATNConfig> lookBusy, BitSet calledRuleStack, boolean seeThruPreds, boolean addEOF) {
    if (calledRuleStack.get(t.target.ruleIndex)) {
        return;
    }

    PredictionContext newContext = SingletonPredictionContext.create(ctx, t.followState.stateNumber);
    try {
        calledRuleStack.set(t.target.ruleIndex);
        _LOOK(t.target, stopState, newContext, look, lookBusy, calledRuleStack, seeThruPreds, addEOF);
    } finally {
        calledRuleStack.clear(t.target.ruleIndex);
    }
}

