protected void lookAhead(@NotNull ATNState state, @Nullable PredictionContext context,
                         @NotNull IntervalSet lookaheadSet, @NotNull Set<ATNConfig> busySet,
                         boolean bypassPredicates, boolean includeEOF) {
    ATNConfig config = new ATNConfig(state, 0, context);
    if (!busySet.add(config)) return;

    if (state instanceof RuleStopState) {
        handleRuleStopState(context, lookaheadSet, includeEOF, state);
        return;
    }

    processTransitions(state, context, lookaheadSet, busySet, bypassPredicates, includeEOF);
}

private void handleRuleStopState(@Nullable PredictionContext context, 
                                  @NotNull IntervalSet lookaheadSet, 
                                  boolean includeEOF, 
                                  ATNState state) {
    if (context == null) {
        lookaheadSet.add(Token.EPSILON);
    } else if (context.isEmpty() && includeEOF) {
        lookaheadSet.add(Token.EOF);
    } else if (context != PredictionContext.EMPTY) {
        for (SingletonPredictionContext predictionContext : context) {
            ATNState returnState = atn.states.get(predictionContext.returnState);
            lookAhead(returnState, predictionContext.parent, lookaheadSet, busySet, bypassPredicates, includeEOF);
        }
    }
}

private void processTransitions(ATNState state, 
                                 @Nullable PredictionContext context, 
                                 @NotNull IntervalSet lookaheadSet, 
                                 @NotNull Set<ATNConfig> busySet, 
                                 boolean bypassPredicates, 
                                 boolean includeEOF) {
    int transitionCount = state.getNumberOfTransitions();
    for (int i = 0; i < transitionCount; i++) {
        Transition transition = state.transition(i);
        if (transition instanceof RuleTransition) {
            PredictionContext newContext = SingletonPredictionContext.create(context, ((RuleTransition) transition).followState.stateNumber);
            lookAhead(transition.target, newContext, lookaheadSet, busySet, bypassPredicates, includeEOF);
        } else if (transition instanceof PredicateTransition) {
            handlePredicateTransition(transition, context, lookaheadSet, busySet, bypassPredicates);
        } else if (transition.isEpsilon()) {
            lookAhead(transition.target, context, lookaheadSet, busySet, bypassPredicates, includeEOF);
        } else if (transition instanceof WildcardTransition) {
            lookaheadSet.addAll(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        } else {
            addTransitionLabelsToLookaheadSet(transition, lookaheadSet);
        }
    }
}

private void handlePredicateTransition(Transition transition, 
                                       @Nullable PredictionContext context, 
                                       @NotNull IntervalSet lookaheadSet, 
                                       @NotNull Set<ATNConfig> busySet, 
                                       boolean bypassPredicates) {
    if (bypassPredicates) {
        lookAhead(transition.target, context, lookaheadSet, busySet, bypassPredicates, includeEOF);
    } else {
        lookaheadSet.add(HIT_PRED);
    }
}

private void addTransitionLabelsToLookaheadSet(Transition transition, @NotNull IntervalSet lookaheadSet) {
    IntervalSet labels = transition.label();
    if (labels != null) {
        if (transition instanceof NotSetTransition) {
            labels = labels.complement(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        }
        lookaheadSet.addAll(labels);
    }
}

protected void _LOOK(@NotNull ATNState s, @Nullable PredictionContext ctx,
                     @NotNull IntervalSet look,
                     @NotNull Set<ATNConfig> lookBusy,
                     boolean seeThruPreds) {
    ATNConfig c = new ATNConfig(s, 0, ctx);
    if (!lookBusy.add(c)) return;

    if (s instanceof RuleStopState) {
        if (ctx == null) {
            look.add(Token.EPSILON);
            return;
        } else if (ctx.isEmpty()) {
            look.add(Token.EOF);
            return;
        }

        if (ctx != PredictionContext.EMPTY) {
            for (SingletonPredictionContext p : ctx) {
                ATNState returnState = atn.states.get(p.returnState);
                _LOOK(returnState, p.parent, look, lookBusy, seeThruPreds);
            }
            return;
        }
    }

    int n = s.getNumberOfTransitions();
    for (int i = 0; i < n; i++) {
        Transition t = s.transition(i);
        if (t.getClass() == RuleTransition.class) {
            PredictionContext newContext = SingletonPredictionContext.create(ctx, ((RuleTransition) t).followState.stateNumber);
            _LOOK(t.target, newContext, look, lookBusy, seeThruPreds);
        } else if (t instanceof PredicateTransition) {
            if (seeThruPreds) {
                _LOOK(t.target, ctx, look, lookBusy, seeThruPreds);
            } else {
                look.add(HIT_PRED);
            }
        } else if (t.isEpsilon()) {
            _LOOK(t.target, ctx, look, lookBusy, seeThruPreds);
        } else if (t.getClass() == WildcardTransition.class) {
            look.addAll(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        } else {
            IntervalSet set = t.label();
            if (set != null) {
                if (t instanceof NotSetTransition) {
                    set = set.complement(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
                }
                look.addAll(set);
            }
        }
    }
}

protected void lookAhead(@NotNull ATNState s, @Nullable PredictionContext ctx,
