public String getDOT(DFA dfa, boolean isLexer) {
    if (dfa.s0 == null) return null;

    ST dot = stlib.getInstanceOf("dfa");
    dot.add("name", "DFA" + dfa.decision);
    dot.add("startState", dfa.s0.stateNumber);
    dot.add("rankdir", rankdir);

    // define stop states first; seems to be a bug in DOT where doublecircle
    for (DFAState d : dfa.states.keySet()) {
        if (d.isAcceptState) {
            addState(dot, d, "stopstate");
        } else if (d.stateNumber != Integer.MAX_VALUE) {
            addState(dot, d, "state");
        }
    }

    for (DFAState d : dfa.states.keySet()) {
        if (d.edges != null) {
            for (int i = 0; i < d.edges.length; i++) {
                DFAState target = d.edges[i];
                if (target != null && target.stateNumber != Integer.MAX_VALUE) {
                    addEdge(dot, d, target, i, isLexer);
                }
            }
        }
    }

    String output = dot.render();
    return Utils.sortLinesInString(output);
}

private void addState(ST dot, DFAState d, String stateType) {
    ST st = stlib.getInstanceOf(stateType);
    st.add("name", "s" + d.stateNumber);
    st.add("label", getStateLabel(d));
    dot.add("states", st);
}

private void addEdge(ST dot, DFAState d, DFAState target, int edgeIndex, boolean isLexer) {
    int ttype = edgeIndex - 1; // we shift up for EOF as -1 for parser
    String label = isLexer ? "\'" + getEdgeLabel(String.valueOf((char) edgeIndex)) + "\'" 
                           : (grammar != null ? grammar.getTokenDisplayName(ttype) : String.valueOf(ttype));
    ST st = stlib.getInstanceOf("edge");
    st.add("label", label);
    st.add("src", "s" + d.stateNumber);
    st.add("target", "s" + target.stateNumber);
    st.add("arrowhead", arrowhead);
    dot.add("edges", st);
}

public String getDOT(DFA dfa, boolean isLexer) {
    if (dfa.s0 == null) return null;

    ST dot = stlib.getInstanceOf("dfa");
    dot.add("name", "DFA" + dfa.decision);
    dot.add("startState", dfa.s0.stateNumber);
    dot.add("rankdir", rankdir);

    addAcceptStates(dfa, dot);
    addNonAcceptStates(dfa, dot);
    addEdges(dfa, dot, isLexer);

    String output = dot.render();
    return Utils.sortLinesInString(output);
}

private void addAcceptStates(DFA dfa, ST dot) {
    for (DFAState state : dfa.states.keySet()) {
        if (!state.isAcceptState) continue;
        ST st = stlib.getInstanceOf("stopstate");
        st.add("name", "s" + state.stateNumber);
        st.add("label", getStateLabel(state));
        dot.add("states", st);
    }
}

private void addNonAcceptStates(DFA dfa, ST dot) {
    for (DFAState state : dfa.states.keySet()) {
        if (state.isAcceptState || state.stateNumber == Integer.MAX_VALUE) continue;
        ST st = stlib.getInstanceOf("state");
        st.add("name", "s" + state.stateNumber);
        st.add("label", getStateLabel(state));
        dot.add("states", st);
    }
}

private void addEdges(DFA dfa, ST dot, boolean isLexer) {
    for (DFAState state : dfa.states.keySet()) {
        if (state.edges != null) {
            for (int i = 0; i < state.edges.length; i++) {
                DFAState target = state.edges[i];
                if (target == null || target.stateNumber == Integer.MAX_VALUE) continue;
                String label = getEdgeLabelForState(i, isLexer);
                ST st = stlib.getInstanceOf("edge");
                st.add("label", label);
                st.add("src", "s" + state.stateNumber);
                st.add("target", "s" + target.stateNumber);
                st.add("arrowhead", arrowhead);
                dot.add("edges", st);
            }
        }
    }
}

private String getEdgeLabelForState(int index, boolean isLexer) {
    int ttype = index - 1; // Shift for EOF
    if (isLexer) {
        return "\'" + getEdgeLabel(String.valueOf((char) index)) + "\'";
    } else if (grammar != null) {
        return grammar.getTokenDisplayName(ttype);
    }
    return String.valueOf(ttype);
}

public String getDOT(DFA dfa, boolean isLexer) {
