                int ttype = i - 1; // we shift up for EOF as -1 for parser
                String label = isLexer ? "\'" + getEdgeLabel(String.valueOf((char) i)) + "\'" : (grammar != null ? grammar.getTokenDisplayName(ttype) : String.valueOf(ttype));

